// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Call as owner (the deployer)
        vm.prank(address(this));
        c.sudicideAnyone();
        // After selfdestruct, contract holds no ether and has no code
        // Reference: c destroyed, mutant: c alive with ether
        assertTrue(address(c).balance == 0 && address(c).code.length == 0);
    }
}
